const byId = new Map(profiles.map(p => [p.id,p]));
const buildSlots = ['cpu','board','gpu','ram','ssd','hdd','psu','case','fan'];
function openBuilder(record) {
  const index = buildSlots.indexOf(record.cat);
  if (index < 0) return '/builder/';
  const parts = Array(buildSlots.length).fill(''); parts[index] = record.id;
  return '/builder/?build=' + encodeURIComponent(parts.join(','));
}
function renderPanel(profile, record, records, esc) {
  const known = new Map(records.map(p=>[p.id,p]));
  const links = profile.alternatives.filter(a=>known.has(a.id));
  return `<!-- program-product:start --><section class="product-program" data-program-product="${esc(profile.id)}" aria-labelledby="product-decision-title">
    <div class="product-program-summary"><h2 id="product-decision-title">What to know before choosing it</h2><p class="product-answer">${esc(profile.answer)}</p><p>${esc(profile.decision)}</p></div>
    <div class="product-program-columns"><section><h3>Source-checked specifications</h3><div class="product-program-table"><table><caption>Manufacturer specifications for the stated model scope</caption><thead><tr><th scope="col">Specification</th><th scope="col">Value</th><th scope="col">Evidence</th></tr></thead><tbody>${profile.facts.map(f=>`<tr><th scope="row">${esc(f.label)}</th><td>${f.value == null?'Needs verification':esc(f.value)+(f.unit?' '+esc(f.unit):'')}${f.note?'<span class="product-fact-note">'+esc(f.note)+'</span>':''}</td><td>${f.value == null?'Unknown':`<a href="${esc(sources[f.sourceId].url)}" target="_blank" rel="noopener noreferrer">${esc(sources[f.sourceId].publisher)} specification</a>`}</td></tr>`).join('')}</tbody></table></div></section>
    <section><h3>Check in your build</h3><ul>${profile.verify.map(t=>'<li>'+esc(t)+'</li>').join('')}</ul><h3>Upgrade and reuse</h3><p>${esc(profile.reuse)}</p><p><a href="/tools/platform-upgrade-cost/">Compare the complete upgrade cost</a></p></section></div>
    <section><h3>Compare realistic alternatives</h3><div class="product-alternatives">${links.map(a=>`<article><h4><a href="/learn/${esc(a.id)}.html">${esc(known.get(a.id).brand+' '+known.get(a.id).name)}</a></h4><p>${esc(a.reason)}</p>${known.get(a.id).cat===record.cat?`<a href="/compare/?mode=interactive&amp;parts=${encodeURIComponent(record.id+','+a.id)}">Compare specifications</a>`:`<a href="/learn/${esc(a.id)}.html">View this alternative</a>`}</article>`).join('')}</div></section>
    <div class="product-program-actions"><a class="button primary" href="${openBuilder(record)}">Open this part in the builder</a>${profile.guides.map(slug=>`<a class="button secondary" href="/blog/${esc(slug)}/">${esc({'how-to-choose-a-graphics-card':'Choose a graphics card','will-a-graphics-card-fit-my-case':'Check GPU fit','rtx-5060-ti-8gb-vs-16gb':'Understand 8 GB vs 16 GB','cpu-or-gpu-upgrade-for-gaming':'Find the upgrade priority','choose-a-pc-power-supply':'Check PSU requirements','am5-upgrade-checklist':'AM5 upgrade checklist','pc-upgrade-total-platform-cost':'Plan the whole platform','b650-tomahawk-m2-pcie-lane-sharing':'Read the slot-sharing guide','choose-a-motherboard-for-your-cpu':'Choose a motherboard','how-to-choose-gaming-ram':'Choose memory','understanding-pc-memory':'Understand memory','nvme-vs-sata-ssd-for-gaming':'Compare NVMe and SATA','choosing-an-ssd':'Choose storage','pc-build-compatibility-checklist':'Build checklist'}[slug]||slug)}</a>`).join('')}</div>
    <details class="product-evidence"><summary>Sources, scope and review status</summary><p>Original manufacturer documents inspected ${date}. These are published specifications and research-based planning notes. This page contains no site-owned hardware test, current price quote or physical fit certification.</p><p>Prepared by PC Part Performance. Status: evidence checked; human editorial review required before publishing this new panel. No human reviewer or publication date is recorded.</p><ul>${profile.sourceIds.map(id=>`<li><a href="${esc(sources[id].url)}" target="_blank" rel="noopener noreferrer">${esc(sources[id].publisher+' — '+sources[id].title)}</a>. ${esc(sources[id].scope)}</li>`).join('')}</ul><p>Exact identity scope: ${esc(profile.identity.model)}${profile.identity.sku?' · '+esc(profile.identity.sku):''}. Unspecified region, revision or SKU remains unknown.</p></details>
  </section><!-- program-product:end -->`;
}

if(!profiles.find(p=>p.id==='rm850x').sourceIds.includes('rmxSku'))profiles.find(p=>p.id==='rm850x').sourceIds.push('rmxSku');

const css = `.product-program{margin:3rem 0;padding:clamp(1.25rem,3vw,2.5rem);border:1px solid var(--line,#ccd3da);border-radius:16px;background:var(--panel,var(--surface));font-size:1rem;line-height:1.65}.product-program h2{font-size:clamp(1.45rem,2.8vw,2rem);line-height:1.2;margin:0 0 1rem;letter-spacing:-.025em}.product-program h3{font-size:1.2rem;line-height:1.3;margin:1.5rem 0 .8rem;letter-spacing:0}.product-program h4{font-size:1.06rem;margin:0 0 .6rem;letter-spacing:0}.product-answer{font-size:1.12rem;max-width:72ch}.product-program-summary>p{max-width:82ch}.product-program-columns{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:clamp(1.5rem,4vw,3rem)}.product-program-table{overflow:auto}.product-program table{width:100%;border-collapse:collapse;text-align:left;font-size:.95rem}.product-program caption{text-align:left;padding:0 0 .75rem;color:var(--muted,#526170)}.product-program th,.product-program td{padding:.8rem .6rem;vertical-align:top;border-bottom:1px solid var(--line,#ccd3da)}.product-program th:first-child{padding-left:0}.product-program td:last-child{min-width:7rem}.product-fact-note{display:block;font-size:.875rem;line-height:1.45;color:var(--muted,#526170);margin-top:.3rem}.product-program li{margin:.6rem 0}.product-alternatives{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,240px),1fr));gap:1rem}.product-alternatives article{border:1px solid var(--line,#ccd3da);border-radius:12px;padding:1.25rem}.product-alternatives article p{margin:.5rem 0 1rem}.product-program-actions{display:flex;gap:.75rem;flex-wrap:wrap;margin:1.5rem 0}.product-program-actions .button{min-height:44px;white-space:normal;text-align:center}.product-evidence{border-top:1px solid var(--line,#ccd3da);padding-top:1rem;margin-top:1.5rem}.product-evidence summary{cursor:pointer;min-height:44px;display:list-item;align-content:center;font-weight:600}.product-evidence p,.product-evidence li{font-size:.925rem}.product-program a:focus-visible,.product-program summary:focus-visible{outline:3px solid var(--accent,#1765b2);outline-offset:4px}.product-program a{text-underline-offset:.2em}@media(max-width:760px){.product-program-columns{grid-template-columns:1fr;gap:.5rem}.product-program table{font-size:.9rem}.product-program-actions .button{flex:1 1 100%}.product-program{margin:2rem 0}.product-program td:last-child{min-width:6rem}}`;

function programProducts({root,records,esc,documentationRoot}) {
  const resolver = createIdentityResolver(records);
  const preview = process.env.PROGRAM_PREVIEW === '1';
  const output = documentationRoot || path.resolve(__dirname,'../docs/program-2026-10-09'); fs.mkdirSync(output,{recursive:true});
  const candidates = new Map();
  for (const p of records) {
    const brand = p.brand.toLowerCase(), name = p.name.toLowerCase();
    const key = brand + ' ' + (name.startsWith(brand+' ')?name.slice(brand.length+1):name);
    if(!candidates.has(key)) candidates.set(key,[]); candidates.get(key).push(p);
  }
  const audit = {date,identityBasis:'explicit_catalog_id',activeAliases:[...resolver.aliases],reviewDecisions:decisions,duplicateNameCandidates:[...candidates].filter(([,items])=>items.length>1).map(([name,items])=>({name,status:'needs_exact_variant_review',ids:items.map(p=>p.id),sources:items.map(p=>p.source)})),priorityCount:profiles.length,priorityBasis:'provisional; no Search Console or keyword-volume measurement',editorialStatus:'evidence_checked; human review required',preview,productionDeployed:false};
  fs.writeFileSync(path.join(output,'product-evidence.json'),JSON.stringify({version:date+'.1',sources,profiles},null,2));
  fs.writeFileSync(path.join(output,'product-integrity-audit.json'),JSON.stringify(audit,null,2));
  fs.writeFileSync(path.join(output,'product-redirect-map.json'),JSON.stringify({version:decisions.version,enabledAliases:[...resolver.aliases],redirects:resolver.redirects(),blocked:decisions.aliases},null,2));
  const missing = profiles.filter(p=>!records.some(record=>record.id===p.id)).map(p=>p.id);
  // The source pipeline now preserves named retail identities. A missing expected ID
  // blocks a panel; it is never replaced by a similarly named product.
  if(missing.length) throw new Error('Priority product ID missing: '+missing.join(', '));
  fs.mkdirSync(path.join(root,'data'),{recursive:true});
  fs.writeFileSync(path.join(root,'data/product-identities.json'),JSON.stringify({version:decisions.version,aliases:Object.fromEntries(resolver.aliases),identityPolicy:'Exact catalog IDs; only explicitly approved aliases.'},null,2));
  fs.writeFileSync(path.join(root,'data/product-evidence.json'),JSON.stringify({version:date+'.1',preparedAt:date,status:preview?'staging_evidence_checked':'not_released',humanReviewed:false,productionDeployed:false,sources,products:profiles.map(p=>({id:p.id,identity:p.identity,facts:p.facts,sourceIds:p.sourceIds,editorial:p.editorial}))},null,2));
  let enhanced = 0;
  for (const record of records) {
    const file = path.join(root,'learn',record.id+'.html'); if(!fs.existsSync(file)) continue;
    let html = fs.readFileSync(file,'utf8').replace(/<!-- program-product:start -->[\s\S]*?<!-- program-product:end -->/g,'').replace(/<link rel="stylesheet" href="\/program-products\.css">/g,'');
    if(html.includes('data-program-added-noindex')) html=html.replace(/\sdata-stage2-noindex(?:="[^"]*")?/g,'');
    html=html.replace(/\sdata-program-(?:product-preview|added-noindex)(?:="[^"]*")?/g,'');
    const p = byId.get(record.id);
    if(preview && p) {
      // Keep this substantive new panel on staging until a human reviews the source/text.
      html = html.replace('</head>','<link rel="stylesheet" href="/program-products.css"></head>');
      if(!html.includes('data-stage2-noindex')) html = html.replace(/<body\b/,'<body data-stage2-noindex data-program-added-noindex');
      html=html.replace(/<body\b/,'<body data-program-product-preview');

      const panel = renderPanel(p,record,records,esc);
      html = html.includes('<div class="record-detail">')?html.replace('<div class="record-detail">',panel+'<div class="record-detail">'):html.replace('</main>',panel+'</main>');
      enhanced++;
    }
    // The two legacy B850 records stay distinct. An explicit contextual link helps
    // readers find the documented model without pretending the old SKU is known.
    html=html.replace(/<!-- program-identity-note:start -->[\s\S]*?<!-- program-identity-note:end -->/g,'');
    if(preview && record.id==='c-board-msi-mag-b850-tomahawk-max-wifi') {
      html=html.replace('</main>','<!-- program-identity-note:start --><p data-product-identity-note>The regional SKU and revision in this legacy record are not verified. <a href="/learn/b850tomahawk.html">Read the documented MAG B850 TOMAHAWK MAX WIFI model specifications</a> before making a BIOS or fit decision.</p><!-- program-identity-note:end --></main>');
    }
    fs.writeFileSync(file,html);
  }
  if(preview) fs.writeFileSync(path.join(root,'program-products.css'),css);
  fs.writeFileSync(path.join(output,'product-template-result.json'),JSON.stringify({date,preview,enhanced,expected:profiles.length,missing,reviewedByHuman:0,publishable:0,productionDeployed:false,sourceCount:Object.keys(sources).length},null,2));
  console.log(`Product program: ${enhanced}/${profiles.length} source-checked staging panels; ${resolver.aliases.size} approved aliases; ${audit.duplicateNameCandidates.length} name-match groups held for exact-identity review.`);
  return {enhanced,profiles,sources,audit};
}
module.exports = programProducts;
Object.assign(module.exports,{profiles,sources,renderPanel,openBuilder,css});
